auto square = [](int x) { return x * x; };
std::vector<int> results;
std::transform(
    std::istream_iterator<int>(std::cin),
    {}, // C++11 EOS literal
    std::back_inserter(results),
    square
);
// Lazily processes input tokens, applying transform efficiently
// Reads 1, processes 1, reads 2, processes 2, etc.
